import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Message(), Error(), and Confirm()","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/message-error-and-confirm.md","filePath":"your-first-al-programs/message-error-and-confirm.md"}`),a={name:`your-first-al-programs/message-error-and-confirm.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="message-error-and-confirm" tabindex="-1"><code>Message()</code>, <code>Error()</code>, and <code>Confirm()</code> <a class="header-anchor" href="#message-error-and-confirm" aria-label="Permalink to “Message(), Error(), and Confirm()”">​</a></h1><p>Business Central provides built-in methods for communicating with users. Three commonly used methods are <code>Message()</code>, <code>Error()</code>, and <code>Confirm()</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th><th>Effect</th></tr></thead><tbody><tr><td><code>Message()</code></td><td>Displays information to the user.</td><td>Does not stop execution.</td></tr><tr><td><code>Error()</code></td><td>Reports a problem that prevents an operation from continuing.</td><td>Stops AL execution and raises an error.</td></tr><tr><td><code>Confirm()</code></td><td>Asks the user a yes/no question.</td><td>Returns a Boolean (<code>true</code> or <code>false</code>).</td></tr></tbody></table><h2 id="message" tabindex="-1"><code>Message()</code> <a class="header-anchor" href="#message" aria-label="Permalink to “Message()”">​</a></h2><p>The <code>Message()</code> method displays an informational message to the user.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><p><strong>Create a new file:</strong> <code>MessageDemo.Codeunit.al</code></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 MessageDemo</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Welcome to Business Central!&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Message(&#39;Your operation completed successfully.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to “Explanation”">​</a></h3><ul><li><code>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</code> — Creates a page extension with ID 50100, named CustomerListExt, that extends the existing Customer List page..</li><li><code>trigger OnOpenPage()</code> — Runs when the page opens.</li><li><code>Message()</code> displays the supplied text to the user.</li><li>Both messages are displayed after the code finishes executing, so the user can see them in sequence.</li></ul><p><strong>Note:</strong> A <code>Message()</code> call does not immediately interrupt execution to display its message. Business Central normally displays queued messages when the AL code finishes or pauses for user interaction.</p><h3 id="displaying-variable-values" tabindex="-1">Displaying Variable Values <a class="header-anchor" href="#displaying-variable-values" aria-label="Permalink to “Displaying Variable Values”">​</a></h3><p>You can use <code>%1</code>, <code>%2</code>, and so on as placeholders for values you want to include in a message.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace DefaultPublisher.HelloWorldBC;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage();</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        CustomerName: Text;</span></span>
<span class="line"><span>        TotalAmount: Decimal;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        CustomerName := &#39;John&#39;;</span></span>
<span class="line"><span>        TotalAmount := 1500;</span></span>
<span class="line"><span>        Message(&#39;Customer : %1. Total amount: %2.&#39;, CustomerName, TotalAmount);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Output:</strong></p><p><img src="/message-output.png" alt="output" width="630" height="313"></p><p>Here, <code>%1</code> is replaced with <code>CustomerName</code>, while <code>%2</code> is replaced with <code>TotalAmount</code>.</p><h2 id="error" tabindex="-1"><code>Error()</code> <a class="header-anchor" href="#error" aria-label="Permalink to “Error()”">​</a></h2><p>The <code>Error()</code> method displays an error message and stops the execution of AL code.</p><p>Use it when an operation cannot safely continue because a business rule has been violated or a required condition has not been met.</p><h3 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace HelloWorld;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage();</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        AvailableStock: Integer;</span></span>
<span class="line"><span>        RequestedQuantity: Integer;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        AvailableStock := 10;</span></span>
<span class="line"><span>        RequestedQuantity := 25;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if RequestedQuantity &gt; AvailableStock then</span></span>
<span class="line"><span>            Error(&#39;Insufficient stock available&#39;);</span></span>
<span class="line"><span>        Message(&#39;Order processed successfully&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="/error-output.png" alt="output" width="724" height="366"></p><h3 id="explanation-1" tabindex="-1">Explanation <a class="header-anchor" href="#explanation-1" aria-label="Permalink to “Explanation”">​</a></h3><ol><li>We have 10 items in stock, but the customer requests 25.</li><li>The <code>if</code> statement checks whether the requested quantity exceeds available stock.</li><li>Since 25 is greater than 10, <code>Error()</code> executes.</li><li>Business Central displays the error and stops execution.</li></ol><p>The message <code>Order processed successfully.</code> is <strong>never displayed</strong> because the error terminates execution before that line is reached.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>When an error occurs during a database transaction, Business Central normally rolls back the transaction&#39;s changes. This helps prevent partially completed operations, although the exact behavior depends on the execution context and transaction boundaries.</p></div><h2 id="confirm" tabindex="-1"><code>Confirm()</code> <a class="header-anchor" href="#confirm" aria-label="Permalink to “Confirm()”">​</a></h2><p>The <code>Confirm()</code> method asks the user a question and returns a Boolean value based on their answer.</p><ul><li><code>true</code> means the user selected <strong>Yes</strong>.</li><li><code>false</code> means the user selected <strong>No</strong>.</li></ul><p>Unlike <code>Message()</code>, <code>Confirm()</code> returns a value that your code can use to decide what happens next.</p><h3 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h3><p><strong>Create a new file:</strong> <code>ConfirmDemo.Codeunit.al</code></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace HelloWorld;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage();</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if Confirm(&#39;Do you want to continue&#39;, false) then</span></span>
<span class="line"><span>            Message(&#39;You chose to continue&#39;)</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;Operation cancelled&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="/confirm-output.png" alt="Output" width="610" height="258"></p><h3 id="explanation-2" tabindex="-1">Explanation <a class="header-anchor" href="#explanation-2" aria-label="Permalink to “Explanation”">​</a></h3><p>The <code>Confirm()</code> method takes two arguments here:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Confirm(&#39;Do you want to continue?&#39;, false)</span></span></code></pre></div><ul><li>The first argument is the question displayed to the user.</li><li>The second argument specifies the default answer. <code>false</code> means <strong>No</strong> is selected by default.</li></ul><p>The <code>if</code> statement evaluates the Boolean value returned by <code>Confirm()</code>.</p><ul><li>If the user selects <strong>Yes</strong>, the first <code>Message()</code> executes.</li><li>If the user selects <strong>No</strong>, the second <code>Message()</code> executes.</li></ul><p>This allows the application to respond differently depending on the user&#39;s decision.</p><h3 id="why-is-confirm-useful" tabindex="-1">Why Is <code>Confirm()</code> Useful? <a class="header-anchor" href="#why-is-confirm-useful" aria-label="Permalink to “Why Is Confirm() Useful?”">​</a></h3><p>Imagine a user is about to delete a customer record. You could ask for confirmation before proceeding.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if Confirm(&#39;Are you sure you want to delete this customer?&#39;, false) then</span></span>
<span class="line"><span>    // Perform the deletion</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    Message(&#39;Deletion cancelled.&#39;);</span></span></code></pre></div><p>This is a simplified illustration of the decision-making logic. Actual deletion code would need to be implemented in the appropriate context.</p><h2 id="quick-comparison" tabindex="-1">Quick Comparison <a class="header-anchor" href="#quick-comparison" aria-label="Permalink to “Quick Comparison”">​</a></h2><p>Consider the following scenarios:</p><ul><li><strong><code>Message()</code></strong>: Inform the user that an operation completed successfully.</li><li><strong><code>Error()</code></strong>: Stop an operation because the requested quantity exceeds available stock.</li><li><strong><code>Confirm()</code></strong>: Ask whether the user wants to proceed with deleting a record.</li></ul><p>Remember that these methods interact with the user interface. Avoid relying on interactive dialogs in background jobs and web service operations, where a user may not be available to respond.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/dialog/dialog-message-method" target="_blank" rel="noreferrer">Dialog.Message Method</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/dialog/dialog-error-string-joker-method" target="_blank" rel="noreferrer">Dialog.Error Method</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/dialog/dialog-confirm-method" target="_blank" rel="noreferrer">Dialog.Confirm Method</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-progress-windows-message-error-and-confirm-methods" target="_blank" rel="noreferrer">Progress Windows, Message, Error, and Confirm Methods</a></li></ul>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};